    _id: 5db6ed14f2e0a60683d8fe42,
    name: 'Infinite Views',
    summary: 'Modern home with infinite views from the infinity pool',
    property_type: 'House',
    bedrooms: 6,
    bathrooms: 4.5,
    beds: 8 
}
```

