    listing_url: 'https://www.airbnb.com/rooms/582364',
    name: 'Spectacular Modern Uptown Duplex',
    property_type: 'Apartment',
    room_type: 'Entire home/apt',
    bedrooms: 4,
    beds: 7
    ...
}
```

