import java.util.AbstractMap

open class Player : RealmObject() {
    var name: String? = null
    var email: String? = null
    var playerHandle: String? = null
    var gameplayStats: RealmDictionary = RealmDictionary()
    var competitionStats: RealmDictionary = RealmDictionary()
}

realm.executeTransactionAsync { r: Realm ->
    val player = Player()
    player.playerHandle = "iDubs"
    // get the RealmDictionary field from the object we just created and add stats
    player.gameplayStats = RealmDictionary(mapOf())
            .apply {
                "mostCommonRole" to "Medic"
                "clan" to "Realmers"
                "favoriteMap" to "Scorpian Bay"
                "tagLine" to "Always be Healin"
                "nemesisHandle" to "snakeCase4Life"
            }
    player.competitionStats = RealmDictionary(mapOf()).apply {
        "EastCoastInvitational" to "2nd Place"
        "TransAtlanticOpen" to "4th Place"
    }
    r.insert(player)
}

// Developer implements a Competitions View -
// emit all entries in the dictionary for view by the user
val player = realm.where().equalTo("name", "iDubs").findFirst()
player?.let {
    player.competitionStats.addChangeListener { map, changes ->
        val insertions = changes.insertions
        for (insertion in insertions) {
            Log.v("EXAMPLE", "Player placed at a new competition $insertion")
        }
    }
}

fun competitionFlow(): Flow = flow {
    for ((competition, place) in player!!.competitionStats) {
        emit("$competition - $place")
    }
}

// Build a RealmQuery that searches the Dictionary type
val query = realm.where().equalTo("name", "iDubs")
val entry = AbstractMap.SimpleEntry("nemesisHandle", "snakeCase4Life")
val playerQuery = query.containsEntry("gameplayStats", entry).findFirst()

// remove player nemesis - they are friends now!
realm.executeTransaction { r: Realm ->
    playerQuery?.gameplayStats?.remove("nemesisHandle")
}
