import android.util.Log
import io.realm.*
import io.realm.kotlin.where

open class Distributor : RealmObject() {
    var name: String = ""
    var transitPolicy: String = ""
}

open class Business : RealmObject() {
    var name: String = ""
    var deliveryMethod: String = ""
}

open class Individual : RealmObject() {
    var name: String = ""
    var salesTerritory: String = ""
}

open class Palette(var owner: RealmAny = RealmAny.nullValue()) : RealmObject() {
    var scanId: String? = null
    open fun ownerToString(): String {
        return when (owner.type) {
            RealmAny.Type.NULL -> {
                "no owner"
            }
            RealmAny.Type.STRING -> {
                owner.asString()
            }
            RealmAny.Type.OBJECT -> {
                when (owner.valueClass) {
                    is Business -> {
                        val business = owner.asRealmModel(Business::class.java)
                        business.name
                    }
                    is Distributor -> {
                        val distributor = owner.asRealmModel(Distributor::class.java)
                        distributor.name
                    }
                    is Individual -> {
                        val individual = owner.asRealmModel(Individual::class.java)
                        individual.name
                    }
                    else -> "unknown type"
                }
            }
            else -> {
                "unknown type"
            }
        }
    }
}

realm.executeTransaction { r: Realm ->
    val newDistributor = r.copyToRealm(Distributor().apply {
        name = "Warehouse R US"
        transitPolicy = "Onsite Truck Pickup"
    })
    val paletteOne = r.copyToRealm(Palette().apply {
        scanId = "A1"
    })
    // Add the owner of the palette as an object reference to another Realm class
    paletteOne.owner = RealmAny.valueOf(newDistributor)
    val newBusiness = r.copyToRealm(Business().apply {
        name = "Mom and Pop"
        deliveryMethod = "Cheapest Private Courier"
    })
    val paletteTwo = r.copyToRealm(Palette().apply {
        scanId = "B2"
        owner = RealmAny.valueOf(newBusiness)
    })
    val newIndividual = r.copyToRealm(Individual().apply {
        name = "Traveling Salesperson"
        salesTerritory = "DC Corridor"
    })
    val paletteThree = r.copyToRealm(Palette().apply {
        scanId = "C3"
        owner = RealmAny.valueOf(newIndividual)
    })
}

// Get a reference to palette one
val paletteOne = realm.where()
        .equalTo("scanId", "A1")
        .findFirst()!!

// Extract underlying Realm Object from RealmAny by casting it RealmAny.Type.OBJECT
val ownerPaletteOne: Palette = paletteOne.owner.asRealmModel(Palette::class.java)
Log.v("EXAMPLE", "Owner of Palette One: " + ownerPaletteOne.ownerToString())

// Get a reference to the palette owned by Traveling Salesperson
// so that you can remove ownership - they're broke!
val salespersonPalette = realm.where()
        .equalTo("owner.name", "Traveling Salesperson")
        .findFirst()!!

val salesperson = realm.where()
        .equalTo("name", "Traveling Salesperson")
        .findFirst()

realm.executeTransaction { r: Realm ->
    salespersonPalette.owner = RealmAny.nullValue()
}

val paletteTwo = realm.where()
        .equalTo("scanId", "B2")
        .findFirst()!!

// Set up a listener to see when Ownership changes for relabeling of palettes
val listener = RealmObjectChangeListener { changedPalette: Palette, changeSet: ObjectChangeSet? ->
    if (changeSet != null && changeSet.changedFields.contains("owner")) {
        Log.i("EXAMPLE",
                "Palette $'paletteTwo.scanId' has changed ownership.")
    }
}

// Observe object notifications.
paletteTwo.addChangeListener(listener)
