import android.util.Log
import io.realm.*
import io.realm.kotlin.where

open class Expert : RealmObject() {
    var name: String = ""
    var email: String = ""
    var disciplines: RealmSet = RealmSet()
}

open class Topic : RealmObject() {
    var name: String = ""
    var location: String = ""
    var discussionThemes: RealmSet = RealmSet()
    var panelists: RealmList = RealmList()
}

realm.executeTransaction { r: Realm ->
    val newExpert = r.copyToRealm(Expert())
    newExpert.name = "Techno King"
    // get the RealmSet field from the object we just created
    val disciplineSet = newExpert.disciplines
    // add value to the RealmSet
    disciplineSet.add("Trance")
    disciplineSet.add("Meme Coins")
    val topic = realm.copyToRealm(Topic())
    topic.name = "Bitcoin Mining and Climate Change"
    val discussionThemes = topic.discussionThemes
    // Add a list of themes
    discussionThemes.addAll(listOf("Memes", "Blockchain", "Cloud Computing",
            "SNL", "Weather Disasters from Climate Change"))
}

// find experts for a discussion topic and add them to the panelists list
val experts: RealmResults = realm.where().findAll()
val topic = realm.where()
        .equalTo("name", "Bitcoin Mining and Climate Change")
        .findFirst()!!
topic.discussionThemes.forEach { theme ->
    experts.forEach { expert ->
        if (expert.disciplines.contains(theme)) {
            topic.panelists.add(expert)
        }
    }
}

//observe the discussion themes set for any changes in the set
val discussionTopic = realm.where()
        .equalTo("name", "Bitcoin Mining and Climate Change")
        .findFirst()
val anotherDiscussionThemes = discussionTopic?.discussionThemes
val changeListener = SetChangeListener { collection: RealmSet,
                                         changeSet: SetChangeSet ->
    Log.v(
            "EXAMPLE",
            "New discussion themes has been added: ${changeSet.numberOfInsertions}"
    )
}

// Observe set notifications.
anotherDiscussionThemes?.addChangeListener(changeListener)

// Techno King is no longer into Meme Coins - remove the discipline
realm.executeTransaction {
    it.where()
            .equalTo("name", "Techno King")
            .findFirst()?.let { expert ->
        expert.disciplines.remove("Meme Coins")
