### The Loader Function

The interesting part is the `loader()` function. Let's create one to first retrieve the first 100 movie documents and leave the search for later.

Add the following code to the `movies/index.jsx` file.

```javascript
export let loader = async ({ request }) => {
    let pipeline = [{ $limit: 100 }];

    let data = JSON.stringify({
        collection: "movies",
        database: "sample_mflix",
        dataSource: process.env.CLUSTER_NAME,
        pipeline
    });

    let config = {
        method: 'post',
        url: `${process.env.DATA_API_BASE_URL}/action/aggregate`,
        headers: {
            'Content-Type': 'application/json',
            'Access-Control-Request-Headers': '*',
            'apiKey': process.env.DATA_API_KEY
        },
        data
    };

    let movies = await axios(config);
    let totalFound = await getCountMovies();

    return {
        showCount: movies?.data?.documents?.length,
        totalCount: totalFound,
        documents: movies?.data?.documents
    };
};

const getCountMovies = async (countFilter) => {
    let pipeline = countFilter ?
        [{ $match: countFilter }, { $count: 'count' }] :
        [{ $count: 'count' }];

    let data = JSON.stringify({
        collection: "movies",
        database: "sample_mflix",
        dataSource: process.env.CLUSTER_NAME,
        pipeline
    });

    let config = {
        method: 'post',
        url: `${process.env.DATA_API_BASE_URL}/action/aggregate`,
        headers: {
            'Content-Type': 'application/json',
            'Access-Control-Request-Headers': '*',
            'apiKey': process.env.DATA_API_KEY
        },
        data
    };

    let result = await axios(config);

    return result?.data?.documents[0]?.count;
}
```

Here we start with an [aggregation pipeline to just limit the first 100 documents for our initial view `pipeline =  {$limit : 100}]; `.  This pipeline will be passed to our REST API call to the Data API endpoint:

``` javascript 
