Before we run the application, let’s go over what’s happening: When we run our main program, we set the connection to our Atlas cluster and our key vault’s collection namespace. We then instantiate two helper classes: a `KmsKeyHelper` and an `AutoEncryptHelper`. The `KmsKeyHelper`’s `CreateKeyWithAzureKmsProvider()` method is called to generate our encrypted data encryption key. This is then passed to the `AutoEncryptHelper`’s `EncryptedWriteAndReadAsync()` method to insert a sample document with encrypted fields and properly decrypt it when we need to fetch it. This is all in our `Program.cs` file:

`Program.cs`

``` cs
using System;
using MongoDB.Driver;

namespace EnvoyMedSys
{
    public enum KmsKeyLocation
    {
        Azure,
    }

    class Program
    {
        public static void Main(string] args)
        {
            var connectionString = Environment.GetEnvironmentVariable("MDB_ATLAS_URI");
            var keyVaultNamespace = CollectionNamespace.FromFullName("encryption.__keyVaultTemp");

            var kmsKeyHelper = new KmsKeyHelper(
                connectionString: connectionString,
                keyVaultNamespace: keyVaultNamespace);
            var autoEncryptHelper = new AutoEncryptHelper(
                connectionString: connectionString,
                keyVaultNamespace: keyVaultNamespace);

            var kmsKeyIdBase64 = kmsKeyHelper.CreateKeyWithAzureKmsProvider().GetAwaiter().GetResult();

            autoEncryptHelper.EncryptedWriteAndReadAsync(kmsKeyIdBase64, KmsKeyLocation.Azure).GetAwaiter().GetResult();

            Console.ReadKey();
        }
    }
}
```

Taking a look at the `KmsKeyHelper` class, there are a few important methods: the `CreateKeyWithAzureKmsProvider()` and `GetClientEncryption()` methods. I’ve opted to include comments in the code to make it easier to follow along:

`KmsKeyHelper.cs` / `CreateKeyWithAzureKmsProvider()`

``` cs
public async Task CreateKeyWithAzureKmsProvider()
{
    var kmsProviders = new Dictionary>();

    // Pull Azure Key Vault settings from environment variables
    var azureTenantId = Environment.GetEnvironmentVariable("AZURE_TENANT_ID");
    var azureClientId = Environment.GetEnvironmentVariable("AZURE_CLIENT_ID");
    var azureClientSecret = Environment.GetEnvironmentVariable("AZURE_CLIENT_SECRET");
    var azureIdentityPlatformEndpoint = Environment.GetEnvironmentVariable("AZURE_IDENTIFY_PLATFORM_ENPDOINT"); // Optional, only needed if user is using a non-commercial Azure instance

   // Configure our registered application settings
   var azureKmsOptions = new Dictionary
    {
        { "tenantId", azureTenantId },
        { "clientId", azureClientId },
        { "clientSecret", azureClientSecret },
    };

    if (azureIdentityPlatformEndpoint != null)
    {
        azureKmsOptions.Add("identityPlatformEndpoint", azureIdentityPlatformEndpoint);
    }

    // Specify remote key location; in this case, Azure
    kmsProviders.Add("azure", azureKmsOptions);

    // Constructs our client encryption settings which
    // specify which key vault client, key vault namespace,
    // and KMS providers to use. 
    var clientEncryption = GetClientEncryption(kmsProviders);

    // Set KMS Provider Settings
    // Client uses these settings to discover the master key
    var azureKeyName = Environment.GetEnvironmentVariable("AZURE_KEY_NAME");
    var azureKeyVaultEndpoint = Environment.GetEnvironmentVariable("AZURE_KEYVAULT_ENDPOINT"); // typically .vault.azure.net
    var azureKeyVersion = Environment.GetEnvironmentVariable("AZURE_KEY_VERSION"); // Optional
    var dataKeyOptions = new DataKeyOptions(
        masterKey: new BsonDocument
        {
            { "keyName", azureKeyName },
            { "keyVaultEndpoint", azureKeyVaultEndpoint },
            { "keyVersion", () => azureKeyVersion, azureKeyVersion != null }
        });

    // Create Data Encryption Key
    var dataKeyId = clientEncryption.CreateDataKey("azure", dataKeyOptions, CancellationToken.None);
    Console.WriteLine($"Azure DataKeyId [UUID]: {dataKeyId}");

    var dataKeyIdBase64 = Convert.ToBase64String(GuidConverter.ToBytes(dataKeyId, GuidRepresentation.Standard));
    Console.WriteLine($"Azure DataKeyId [base64]: {dataKeyIdBase64}");

    // Optional validation; checks that key was created successfully
    await ValidateKeyAsync(dataKeyId);

    return dataKeyIdBase64;
}
```

`KmsKeyHelper.cs` / `GetClientEncryption()`

``` cs
private ClientEncryption GetClientEncryption(
Dictionary> kmsProviders)
{
    // Construct a MongoClient using our Atlas connection string
    var keyVaultClient = new MongoClient(_mdbConnectionString);

    // Set MongoClient, key vault namespace, and Azure as KMS provider
    var clientEncryptionOptions = new ClientEncryptionOptions(
     keyVaultClient: keyVaultClient,
        keyVaultNamespace: _keyVaultNamespace,
        kmsProviders: kmsProviders);

    return new ClientEncryption(clientEncryptionOptions);
}
```

With our Azure Key Vault connected and data encryption key encrypted, we’re ready to insert some data into our Atlas cluster! This is where the `AutoEncryptHelper` class comes in. The important method to note here is the `EncryptedReadAndWrite()` method:

`AutoEncryptHelper.cs` / `EncryptedReadAndWrite()`

``` cs
public async Task EncryptedWriteAndReadAsync(string keyIdBase64, KmsKeyLocation kmsKeyLocation)
{
    // Construct a JSON Schema
    var schema = JsonSchemaCreator.CreateJsonSchema(keyIdBase64);

    // Construct an auto-encrypting client
    var autoEncryptingClient = CreateAutoEncryptingClient(
        kmsKeyLocation,
        _keyVaultNamespace,
        schema);

    // Set our working database and collection to medicalRecords.patientData
    var collection = autoEncryptingClient
        .GetDatabase(_medicalRecordsNamespace.DatabaseNamespace.DatabaseName)
        .GetCollection(_medicalRecordsNamespace.CollectionName);

    var ssnQuery = Builders.Filter.Eq("ssn", __sampleSsnValue);

    // Upsert (update if found, otherwise create it) a document into the collection
    var medicalRecordUpdateResult = await collection
        .UpdateOneAsync(ssnQuery, new BsonDocument("$set", __sampleDocFields), new UpdateOptions() { IsUpsert = true });

    if (!medicalRecordUpdateResult.UpsertedId.IsBsonNull)
    {
        Console.WriteLine("Successfully upserted the sample document!");
    }

    // Query by SSN field with auto-encrypting client
    var result = await collection.Find(ssnQuery).SingleAsync();

    // Proper result in console should show decrypted, human-readable document
    Console.WriteLine($"Encrypted client query by the SSN (deterministically-encrypted) field:\n {result}\n");
}
```

