      "deployments.region": "HK",
    },
  },
  {
    $lookup: {
      from: "APIMetrics",
      let: {
        apiName: "$apiDetails.appname",
      },
      pipeline: [
        {
          $match: {
            $expr: {
              $and: [
                {
                  $eq: ["$apiDetails.appname", "$$apiName"],
                },
                {
                  $gte: [
