            },
          },
        },
        {
          $group: {
            _id: "apiDetails.appName",
            totalVolume: {
              $sum: "$transactionVolume",
            },
            totalError: {
              $sum: "$errorCount",
            },
            totalSuccess: {
              $sum: "$successCount",
            },
          },
        },
        {
          $project: {
            aggregatedResponse: {
              totalTransactionVolume: "$totalVolume",
              errorRate: {
                $cond: [
                  {
                    $eq: ["$totalVolume", 0],
                  },
                  0,
                  {
                    $multiply: [
