        status: &u8,
        rmt_channel: impl Peripheral,
        led_pin: impl Peripheral,
    ) -> ! {
        let mut neopixel =
            Ws2812Esp32RmtDriver::new(rmt_channel, led_pin).expect("Unable to talk to ws2812");
        loop {}
    }
