        #[default("NotMyWifi")]
        wifi_ssid: &'static str,
        #[default("NotMyPassword")]
        wifi_password: &'static str,
        #[default("mqttserver")]
        mqtt_host: &'static str,
        #[default("")]
        mqtt_user: &'static str,
        #[default("")]
        mqtt_password: &'static str,
